cat /app/resources/treasury_bulletin_2010_06.json | python3 -c "
import json, sys
data = json.load(sys.stdin)
# Search for elements with tables that have Dec 2010 or later months
for i, elem in enumerate(data.get('document', {}).get('elements', [])):
    content = elem.get('content', '')
    if content and '2010' in str(content):
        if 'Dec. 2010' in str(content) or 'Dec 2010' in str(content) or ('2010' in str(content) and 'Dec' in str(content)):
            print(f'Element {i}: {str(content)[:600]}')" 2>/dev/null | head -30
